cd /workspace/project && python3 - <<'PY'
from syntax import parse_policy,PolicyError
# chain not depth n: n not around atom gives depth n+1
for n in [14,15,16,17]:
 s='not('*n+'match(A)'+')'*n+' allow;'
 try:
  p=parse_policy(s);print('not',n,'ok atoms',p.atoms)
 except PolicyError as e:print('not',n,'reject',e)
# binary right chain depth n => n-1 binaries
for n in [14,15,16,17]:
 # depth1 atom, wrap n-1 times: (pred and match(B)) => depth+1
 s='match(A)'
 for i in range(n-1):s='('+s+' and match(B))'
 s+=' allow;'
 try:
  p=parse_policy(s);print('bin',n,'ok')
 except PolicyError as e:print('bin',n,'reject',e)
# atoms bounds
for n in [32,33]:
 s='('+' and '.join(['match(A)']*n)+') allow;' # complex; binary nesting too high if n>17! Use balanced? here left chain depth n
 try:p=parse_policy(s);print('atoms',n,'ok')
 except PolicyError as e:print('atoms',n,'reject',e)
# Path lengths
for n in [16,17]:
 s='match('+','.join(['A']*n)+') allow;'
 try:p=parse_policy(s);print('path',n,'ok',p.path_symbols)
 except PolicyError as e:print('path',n,'reject',e)
# nonmatch length
for n in [4,5]:
 s='contains('+','.join(['A']*n)+') allow;'
 try:p=parse_policy(s);print('nm path',n,'ok')
 except PolicyError as e:print('nm path',n,'reject',e)
# complex count
for n in [8,9]:
 s=''.join('not(match(A)) allow;' for _ in range(n))
 try:p=parse_policy(s);print('complex',n,'ok')
 except PolicyError as e:print('complex',n,'reject',e)
PY
